module multi_pipe_8bit (
    input           clk,
    input           rst_n,
    input           mul_en_in,
    input   [7:0]   mul_a,
    input   [7:0]   mul_b,
    output          mul_en_out,
    output  [15:0]  mul_out
);

    // Registers for input enable pipelining (1-bit enable signal extended as shift reg for pipeline stages)
    reg [4:0] mul_en_out_reg;

    // Input operand registers, loaded only when mul_en_in is asserted
    reg [7:0] mul_a_reg;
    reg [7:0] mul_b_reg;

    // Partial products (wires) generated by ANDing multiplicand with each bit of multiplier
    wire [15:0] temp[7:0];
    integer i;
    // Generate partial products by shifting multiplicand according to multiplier bits
    generate
        genvar gi;
        for (gi=0; gi<8; gi=gi+1) begin : PARTIAL_PRODUCT_GEN
            assign temp[gi] = mul_b_reg[gi] ? ({mul_a_reg, 8'b0} >> (8-gi)) : 16'b0;
            // Explanation:
            // mul_a_reg shifted left by gi bits = mul_a_reg << gi, but here done as (mul_a_reg,8'b0) >> (8-gi) equals mul_a_reg << gi
            // To avoid using shift left on concatenation, simpler to use left shift directly:
            // Let's fix that to simpler left shift.
        end
    endgenerate

    // Fix partial product generation (simpler version):
    wire [15:0] pp[7:0];
    assign pp[0] = mul_b_reg[0] ? {8'b0, mul_a_reg} << 0 : 16'b0;
    assign pp[1] = mul_b_reg[1] ? {8'b0, mul_a_reg} << 1 : 16'b0;
    assign pp[2] = mul_b_reg[2] ? {8'b0, mul_a_reg} << 2 : 16'b0;
    assign pp[3] = mul_b_reg[3] ? {8'b0, mul_a_reg} << 3 : 16'b0;
    assign pp[4] = mul_b_reg[4] ? {8'b0, mul_a_reg} << 4 : 16'b0;
    assign pp[5] = mul_b_reg[5] ? {8'b0, mul_a_reg} << 5 : 16'b0;
    assign pp[6] = mul_b_reg[6] ? {8'b0, mul_a_reg} << 6 : 16'b0;
    assign pp[7] = mul_b_reg[7] ? {8'b0, mul_a_reg} << 7 : 16'b0;

    // Pipeline registers for partial sums - to break addition into stages
    // We'll pipeline the addition in multiple stages:
    // Stage 1: sum0 = pp0 + pp1, sum1 = pp2 + pp3, sum2 = pp4 + pp5, sum3 = pp6 + pp7
    reg [15:0] sum0, sum1, sum2, sum3;
    // Stage 2: sum01 = sum0 + sum1, sum23 = sum2 + sum3
    reg [15:0] sum01, sum23;
    // Stage 3: final sum = sum01 + sum23
    reg [15:0] mul_out_reg;

    // Pipeline stages for enable signals to indicate valid data
    // mul_en_out_reg is 5 bits for 5 stages: input register + 3 pipeline additions + output register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            mul_en_out_reg <= 5'b0;
        else
            mul_en_out_reg <= {mul_en_out_reg[3:0], mul_en_in};
    end

    // Input operand registers, capture when mul_en_in is high
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            mul_a_reg <= 8'b0;
            mul_b_reg <= 8'b0;
        end else if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
    end

    // Pipeline Stage 1: Pairwise addition of partial products
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum0 <= 16'b0;
            sum1 <= 16'b0;
            sum2 <= 16'b0;
            sum3 <= 16'b0;
        end else if (mul_en_out_reg[1]) begin
            sum0 <= pp[0] + pp[1];
            sum1 <= pp[2] + pp[3];
            sum2 <= pp[4] + pp[5];
            sum3 <= pp[6] + pp[7];
        end else begin
            sum0 <= 16'b0;
            sum1 <= 16'b0;
            sum2 <= 16'b0;
            sum3 <= 16'b0;
        end
    end

    // Pipeline Stage 2: Add results of stage 1 pairs
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum01 <= 16'b0;
            sum23 <= 16'b0;
        end else if (mul_en_out_reg[2]) begin
            sum01 <= sum0 + sum1;
            sum23 <= sum2 + sum3;
        end else begin
            sum01 <= 16'b0;
            sum23 <= 16'b0;
        end
    end

    // Pipeline Stage 3: Final addition
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            mul_out_reg <= 16'b0;
        else if (mul_en_out_reg[3])
            mul_out_reg <= sum01 + sum23;
        else
            mul_out_reg <= 16'b0;
    end

    // Output enable is MSB of mul_en_out_reg (5th stage)
    assign mul_en_out = mul_en_out_reg[4];

    // Output mux: output product only when mul_en_out is asserted, else zero
    assign mul_out = mul_en_out ? mul_out_reg : 16'b0;

endmodule